#### Define Cleaning Functions ####
# Clean publication records to clean variable names, remove embedded HTM,
# identify pre-print articles and conver up white space only values to NA.
# @param df Cleaned publications data frame
# @param project_id is the name of an NIH Initiative
clean_publications_data <- function(df, consortia) {
  
  cat("\nCleaning", consortia, "publications data...\n")
  
  df_clean <- df %>%
    
    # Clean column names - remove parenthetical text from variable names
    janitor::clean_names() %>%
    
    # Manually rename columns to avoid duplicates after removing parenthetical text
    # This preserves the distinction between PubMed and Google Scholar versions
    rename_with(
      ~ case_when(
        str_detect(., "title.*link.*full.*text") ~ "title",
        str_detect(., "journal.*link.*pub_med") ~ "journal",
        TRUE ~ .
      ),
      everything()
    ) %>%
    
    # Additional HTML cleanup - remove any remaining tags
    mutate(across(
      c(title,
        journal),
      ~ if_else(!is.na(.), str_remove_all(., "<.*?>"), NA_character_)
    )) %>%
    
    # Removes variables that are not used.
    select(-related_publications_in_pub_med, 
           -related_publications_in_google_scholar,
           -articles_citing_from_pub_med_central,
           -articles_citing_from_google_scholar) %>%
    
    # Create preprint flag
    # Preprints typically appear in bioRxiv, medRxiv, arXiv, Research Square, etc.
    mutate(
      is_preprint = case_when(
        is.na(journal) ~ NA,
        str_detect(tolower(journal), 
                   "biorxiv|medrxiv|arxiv|research square|preprints|ssrn|chemrxiv|eartharxiv") ~ TRUE,
        TRUE ~ FALSE
      )
    ) %>%
    
    # Remove completely empty rows
    filter(!if_all(everything(), is.na)) %>%
    
    # Sort by publications by title, pub_year
    arrange(title, desc(pub_year))
  
  # Remove white space only values with NAs 
  df_clean[1:20] <- lapply(df_clean[,c(1:20)], function(x) gsub("^\\s+|\\s+$", "", x))
  df_clean[df_clean == ""] <- NA
  
  return(df_clean)
}

# Flag pre-prints that match published articles.
# @param df Cleaned publications data frame
# @return Same data frame with preprint_matched flag added
flag_preprint_matches <- function(df) {
  
  cat("\nIdentifying preprint-to-publication matches...\n")
  
  # Ensure is_preprint is logical
  df <- df %>%
    mutate(is_preprint = as.logical(is_preprint))
  
  # Initialize the new columns
  df$preprint_matched <- FALSE
  df$matched_pmid <- NA_character_
  
  # Get indices of preprints and publications
  preprint_rows <- which(df$is_preprint == TRUE & !is.na(df$is_preprint))
  pub_rows <- which(df$is_preprint == FALSE | is.na(df$is_preprint))
  
  if (length(preprint_rows) == 0) {
    cat("  No preprints found in dataset\n")
    return(df)
  }
  
  cat("  Found", length(preprint_rows), "preprints to check\n")
  
  # Normalize text helper
  normalize_text <- function(text) {
    tolower(text) %>%
      str_remove_all("[[:punct:]]") %>%
      str_squish()
  }
  
  # Check each preprint
  n_matched <- 0
  for (i in preprint_rows) {
    preprint_title <- normalize_text(df$title[i])
    preprint_authors <- normalize_text(df$authors[i])
    
    # Skip if missing title
    if (is.na(preprint_title) || preprint_title == "") next
    
    # Compare to all publications
    for (j in pub_rows) {
      pub_title <- normalize_text(df$title[j])
      pub_authors <- normalize_text(df$authors[j])
      
      # Skip if missing title
      if (is.na(pub_title) || pub_title == "") next
      
      # Check title similarity
      title_dist <- stringdist::stringdist(preprint_title, pub_title, method = "jw")
      
      # If titles are very similar (< 0.15 distance)
      if (title_dist < 0.15) {
        # Check author similarity if both exist
        if (!is.na(preprint_authors) && !is.na(pub_authors)) {
          author_dist <- stringdist::stringdist(preprint_authors, pub_authors, method = "jw")
          author_sim <- 1 - author_dist
          
          # If authors also match well (> 0.7 similarity)
          if (author_sim > 0.7) {
            df$preprint_matched[i] <- TRUE
            df$matched_pmid[i] <- df$pmid[j]
            n_matched <- n_matched + 1
            break  # Stop looking once we find a match
          }
        }
      }
    }
  }
  
  cat("  Matched", n_matched, "preprints to published articles\n")
  cat("  Unmatched preprints:", length(preprint_rows) - n_matched, "\n")
  
  return(df)
}

# Adds a count of author based on author list string patterns
# @param df Cleaned publications data frame
# @return Same data frame with author_count variable added
add_author_count <- function(df) {
  # Add author count to the publication list.

  df_author_ct <- 
    df %>%
    mutate(author_count = stringr::str_count(authors, "; ")+1)

  return(df_author_ct)
}

# Adds a count of divisions reporting a publication 
# @param df Cleaned publications data frame for a consortia
# @return Same data frame with author_count variable added
calc_pub_division_counts <- function(df) {
  # Add author count to the publication list.
  tmp <- 
    df %>%
    select(pmid, division) %>%
    group_by(pmid) %>%
    summarise(division_count = n_distinct(division)) %>%
    ungroup() 
  
  return(tmp)
  rm(tmp)
}

