rm(htan_pub_lookup,sennet_pub_lookup,hubmap_pub_lookup)

# Calculate atlas projects and divisions publications associations
# Count of atlas projects associated with a publication
pmid_project_score <- 
  project_award_pub_lookup %>%
  pivot_wider(id_cols = pmid,
              names_from = c(consortia),
              names_glue = paste0("{consortia}_projects"),
              values_from = value,
              values_fn = sum,
              values_fill= 0)

# Count of atlas division projects associated with a publication.
pmid_division_score <- 
  project_award_pub_lookup %>%
  pivot_wider(id_cols = pmid,
              names_from = c(division),
              names_glue = paste0("{division}_projects"),
              values_from = value,
              values_fn = sum,
              values_fill= 0)
pmid_division_score <-
  janitor::clean_names(pmid_division_score)

# Combine publication level calculations
pmid_metadata <- 
  left_join(pmid_project_score,
            pmid_division_score, by = "pmid")

# Identify consortia publications
