pmid_metadata[pmid_metadata$SenNet_projects>0,]$SenNet_index <- 1
pmid_metadata[pmid_metadata$HTAN_projects>0,]$HTAN_index <- 1

# Check for publications with multiple consortia project collaborations
pmid_metadata$division_collaboration <- 0
pmid_metadata[pmid_metadata$HTAN_projects > 1 | 
              pmid_metadata$SenNet_projects > 1 |
              pmid_metadata$HuBMAP_projects > 1, ]$division_collaboration <- 1


